	private static FilterPlan directPlan(NativeLmdbQuerySource source, boolean nullable) {
		long yes = id(source, "yes");
		SlotPlan input = new UnionPlan(pattern(source, 1, "candidate", Term.slot(0), 2D),
				nullable ? pattern(source, 1, "unboundMarker", Term.constant(yes), 1D)
						: pattern(source, 1, "candidate", Term.slot(0), 2D));
		PatternPlan seed = pattern(source, 2, "anchor", Term.constant(yes), 1D);
		SlotPlan right = new ExtensionPlan(pattern(source, 0, "witness", Term.constant(yes), 1D),
				new CopyBinding[] { CopyBinding.constant(3, yes) });
		NativeBooleanFilter bound = new NativeBooleanFilter() {
			@Override
			public boolean accept(RowState candidate) {
				return candidate.view.hasBinding("marker");
			}

			@Override
			public long batchReadMask() {
				return 1L << 3;
			}
		};
		SlotPlan body = new FilterPlan(new LeftJoinPlan(seed, right), bound, 1L << 3);
		return new FilterPlan(input, new ExistsFilter(body), 1L);
	}

	private static PatternPlan pattern(NativeLmdbQuerySource source, int subject, String predicate,
			Term object, double rows) {
		return new PatternPlan(Term.slot(subject), Term.constant(id(source, predicate)), object, Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, null, "", null, rows, source.indexAccessProfile());
	}

	private static long id(NativeLmdbQuerySource source, String local) {
		return source.idOf(org.eclipse.rdf4j.model.impl.SimpleValueFactory.getInstance().createIRI(NS + local));
	}

	private static List<String> directRows(SyntheticValueSource source, NativeSlotLayout layout, SlotPlan input,
			String forcing) throws Exception {
		LmdbNativeEvaluationStrategy strategy = mock(LmdbNativeEvaluationStrategy.class);
		when(strategy.forcedExecutionStrategyName()).thenReturn(forcing);
		NativeRowsStep step = new NativeRowsStep(source, input, layout, new int[] { 1, 0 },
				new String[] { "row", "s" }, false, new int[0], new boolean[0], 0L, -1L, false,
				strategy, null, null, Set.of(), null, null);
		List<String> result = new ArrayList<>();
		List<LmdbNativeDecisionTestAccess.Selected> selected = new ArrayList<>();
		try (AutoCloseable ignored = LmdbNativeDecisionTestAccess.captureSelections(selected);
				NativeRowsIteration rows = new NativeRowsIteration(step, source, EmptyBindingSet.getInstance())) {
			while (rows.hasNext()) {
				var bindings = rows.next();
				result.add(bindings.getValue("row").stringValue() + "|"
						+ (bindings.hasBinding("s") ? bindings.getValue("s").stringValue() : "<unbound>"));
			}
		}
		assertThat(selected).singleElement()
				.satisfies(selection -> assertThat(selection.id()).isIn((Object[]) forcing.split(",")));
		System.out.println("direct nullable OPTIONAL route=" + forcing + " bag=" + result);
		return result.stream().sorted().toList();
	}

	private static List<String> rows(SailRepository repository, String forced, boolean nullable) {
		List<String> result = new ArrayList<>();
		try (var connection = repository.getConnection()) {
			String sparql = nullable ? QUERY : QUERY.replace("{ ?row :unboundMarker :yes }", "{ ?row :candidate ?s }");
			SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(sparql);
			query.setForcedLmdbExecutionStrategy(forced);
			try (var rows = query.evaluate()) {
				while (rows.hasNext()) {
					var row = rows.next();
					result.add(row.getValue("row").stringValue() + "|"
							+ (row.hasBinding("s") ? row.getValue("s").stringValue() : "<unbound>"));
				}
			}
		}
		return result.stream().sorted().toList();
	}
